class TransactionStore:
    """A key-value store with arbitrarily nested transactions.

    Each scope is a layer of overrides rather than a copy of the data, so
    nesting costs a dict and committing one layer is a single merge.
    """

    def __init__(self):
        # Layer 0 is the committed state; later layers are open scopes.
        self.layers = [{}]
        # A sentinel for a delete, because None is a legal value to store.
        self.deleted = object()

    def get(self, key):
        # Newest layer wins, so a read sees everything written in this scope
        # and everything its ancestors committed.
        for layer in reversed(self.layers):
            if key in layer:
                value = layer[key]
                return None if value is self.deleted else value
        return None

    def set(self, key, value):
        self.layers[-1][key] = value

    def delete(self, key):
        # Recorded as an override rather than a removal, so the delete is
        # visible inside the transaction and undone by a rollback.
        self.layers[-1][key] = self.deleted

    def begin(self):
        self.layers.append({})

    def commit(self):
        if len(self.layers) == 1:
            raise ValueError('No transaction')
        # Merged upward rather than applied, which is what makes a nested
        # commit affect only the innermost scope.
        changes = self.layers.pop()
        self.layers[-1].update(changes)

    def rollback(self):
        if len(self.layers) == 1:
            raise ValueError('No transaction')
        # Simply dropping the layer discards it, and leaves every enclosing
        # scope exactly as it was.
        self.layers.pop()

