def resolve_path(cwd, path):
    """Resolve a path as a shell would, using a component stack.

    Pure string processing: nothing here touches the filesystem or follows a
    symbolic link.
    """
    # An absolute path ignores the working directory; a relative one starts
    # from it.
    parts = [] if path.startswith('/') else [p for p in cwd.split('/') if p]

    for p in path.split('/'):
        if p in ('', '.'):
            # Repeated slashes and no-op components disappear.
            continue
        if p == '..':
            if parts:
                # `..` at the root is ignored rather than an error, so a
                # path that walks above the root clamps to `/`.
                parts.pop()
        else:
            parts.append(p)

    return '/' + '/'.join(parts)

