class Autocomplete:
    """Prefix search over a dictionary, backed by a trie.

    A trie shares the common prefix between words instead of comparing every
    word from the start, so a query costs the length of the prefix.
    """

    def __init__(self):
        self.root = {}

    def add(self, word):
        node = self.root
        for c in word:
            # setdefault builds a path in one expression; a child dict is a
            # node, and None marks a word that ends here.
            node = node.setdefault(c, {})
        node[None] = True

    def suggest(self, prefix, k):
        if k <= 0:
            return []
        # Walk the prefix once. A prefix that is not a path has no matches.
        node = self.root
        for c in prefix:
            if c not in node:
                return []
            node = node[c]

        result = []
        # An explicit stack, because the recursion depth would be the length
        # of the longest word.
        stack = [(node, prefix)]
        while stack and len(result) < k:
            current, word = stack.pop()
            if None in current:
                # A word can be reached by more than one path, so it is
                # deduplicated by only ever being appended from its own node.
                result.append(word)
            # Pushed in reverse so the stack pops them in ascending order,
            # which is what makes the output lexicographic.
            for c in sorted((c for c in current if c is not None), reverse=True):
                stack.append((current[c], word + c))
        return result

def can_assign(jobs, capacities):
    """Whether every job fits whole into some machine's remaining capacity."""
    # Largest first, so the search fails fast on the tightest decisions.
    work = sorted(jobs, reverse=True)
    remaining = list(capacities)
    if sum(work) > sum(remaining):
        # A total-capacity shortfall cannot be fixed by any arrangement.
        return False

    def search(i):
        if i == len(work):
            return True
        tried = set()
        for w, capacity in enumerate(remaining):
            if capacity < work[i] or capacity in tried:
                # A job goes to exactly one machine, and two machines with
                # equal remaining capacity lead to identical subtrees.
                continue
            tried.add(capacity)
            remaining[w] -= work[i]
            if search(i + 1):
                remaining[w] += work[i]
                return True
            # Undo before trying the next machine.
            remaining[w] += work[i]
        return False

    return search(0)

