def retry(operation, attempts, retry_on=(TimeoutError,)):
    """Call an operation, retrying only the given exception types."""
    if attempts < 1:
        raise ValueError('attempts must be positive')
    for i in range(attempts):
        try:
            # The result is returned directly. None, 0, False and the empty
            # string are all successful answers, so the truthiness of what
            # came back must never decide whether this call succeeded.
            return operation()
        except retry_on:
            if i == attempts - 1:
                # The last retryable failure re-raises the original error, so
                # the caller can see why it kept failing.
                raise

