from collections import defaultdict


class SearchIndex:
    """An inverted index mapping each term to the documents containing it."""

    def __init__(self):
        # doc id -> the terms it contains, so re-adding can clear the old ones.
        self.docs = {}
        # term -> set of doc ids.
        self.index = defaultdict(set)

    def add(self, doc_id, text):
        # Removing the previous posting lists first is what makes re-adding a
        # document replace its content rather than merge into it.
        for term in self.docs.get(doc_id, set()):
            self.index[term].discard(doc_id)
        # lower().split() keeps punctuation, which documents and queries both
        # still contain.
        terms = set(text.lower().split())
        self.docs[doc_id] = terms
        for term in terms:
            self.index[term].add(doc_id)

    def search(self, query):
        terms = set(query.lower().split())
        if not terms:
            return []
        # Every query term must be present, so this is an intersection of
        # posting lists. Intersecting the smallest first keeps it cheap: the
        # result can never be larger than the smallest list.
        postings = sorted((self.index.get(t, set()) for t in terms), key=len)
        matches = postings[0].copy()
        for posting in postings[1:]:
            matches.intersection_update(posting)
        return sorted(matches)

