class Node:
    """One cluster member: a membership vector plus the count it derives.

    The vector is keyed by origin so a merge is a union per key, which keeps
    the thing a node gossips stable in shape as the cluster grows.
    """

    def __init__(self, node_id):
        self.node_id = node_id
        # Membership vector: node id -> the ids that node has advertised here.
        self.known = {node_id: {node_id}}
        # The union of every set in `known`, held alongside it. Merging adds
        # only the genuinely new ids, so count() never walks the vector.
        self.seen = {node_id}
        # Monotone count of ids ever learned, so the driver can ask whether a
        # round moved anything without diffing a single vector.
        self.gained = 0

    def merge(self, payload):
        """Union a neighbour's membership vector in; return ids newly learned."""
        learned = 0
        for origin, peers in payload.items():
            self.known.setdefault(origin, set()).update(peers)
            # Subtracted from the union, not from this origin's set: an id two
            # neighbours both advertise is still one node, not two.
            fresh = peers - self.seen
            if fresh:
                self.seen |= fresh
                learned += len(fresh)
        self.gained += learned
        return learned

    def count(self):
        # O(1). A count that re-walked `known` would be O(V) per call, and
        # asking every node for one per round turns the loop quadratic for no
        # reason: the merge already knows how much arrived.
        return len(self.seen)

    def converged(self, truth):
        # Measured against ground truth the harness owns. A node cannot tell it
        # is converged by looking at its own set -- it can only be wrong about
        # the size of a component it is not in.
        return self.count() == truth.get(self.node_id)


class Channel:
    """An unordered link that may duplicate a message or lose it entirely."""

    def __init__(self):
        self.queue = []
        self.sent = 0
        self.delivered = 0
        self.drop_period = 0
        self.duplicate_period = 0

    def duplicate_every(self, k):
        """Queue every k-th send twice. 0 disables duplication."""
        self.duplicate_period = k
        return self

    def drop_every(self, k):
        """Discard every k-th send. 0 disables loss."""
        self.drop_period = k
        return self

    def send(self, sender, recipient, payload):
        """Queue one message. Returns False when the link swallowed it."""
        index = self.sent
        self.sent += 1
        if self.drop_period and (index + 1) % self.drop_period == 0:
            return False
        # A snapshot, not a live reference: the sender goes on merging after the
        # send, and a shared set would let a claim mutate in the queue, so the
        # channel would deliver something no node ever said.
        message = {origin: set(peers) for origin, peers in payload.items()}
        self.queue.append((sender, recipient, message))
        if self.duplicate_period and (index + 1) % self.duplicate_period == 0:
            self.queue.append((sender, recipient, message))
        return True

    def deliver_all(self):
        """Deliver everything queued, in send order. Returns the message count."""
        pending, self.queue = self.queue, []
        for _sender, recipient, message in pending:
            recipient.merge(message)
        self.delivered += len(pending)
        return len(pending)


def neighbours(node_ids, adjacency):
    """Undirected neighbours per node; ids outside the cluster are ignored."""
    live = set(node_ids)
    links = {node_id: set() for node_id in node_ids}
    for node_id, adjacent in adjacency.items():
        if node_id not in live:
            continue
        for other in adjacent:
            if other in live:
                # The wire works both ways, so one entry in either direction
                # gives both nodes a link.
                links[node_id].add(other)
                links[other].add(node_id)
    return links


def component_sizes(node_ids, adjacency):
    """Ground truth: the true size of the component each node belongs to."""
    links = neighbours(node_ids, adjacency)
    sizes = {}
    for start in node_ids:
        if start in sizes:
            continue
        seen = {start}
        stack = [start]
        while stack:
            for other in links[stack.pop()]:
                if other not in seen:
                    seen.add(other)
                    stack.append(other)
        for node_id in seen:
            sizes[node_id] = len(seen)
    return sizes


def run(net, node_ids, adjacency, rounds):
    """Drive the protocol for at most `rounds` rounds of gossip.

    Returns {"counts": ..., "converged": ..., "rounds": ...}. Convergence is
    measured against component_sizes rather than inferred from the loop
    stopping, because stopping early is not the same as being right.
    """
    nodes = {node_id: Node(node_id) for node_id in node_ids}
    truth = component_sizes(node_ids, adjacency)
    wired = neighbours(node_ids, adjacency)
    # Sorted so the loss and duplication patterns hit the same sends every run.
    links = sorted((a, b) for a in node_ids for b in wired[a])
    used = 0
    for _ in range(rounds):
        used += 1
        before = sum(node.gained for node in nodes.values())
        for source, target in links:
            net.send(nodes[source], nodes[target], nodes[source].known)
        net.deliver_all()
        # A node only ever grows, so comparing the monotone totals says
        # whether the round moved anything without diffing any vector.
        if sum(node.gained for node in nodes.values()) == before:
            break
    counts = {node_id: nodes[node_id].count() for node_id in node_ids}
    converged = all(nodes[node_id].converged(truth) for node_id in node_ids)
    return {"counts": counts, "converged": converged, "rounds": used}

