import json


def _factory(source):
    # A callable can be run again, so it is the natural source. Anything else
    # has to be iterable more than once, which is exactly why a bare
    # generator is not usable here: it cannot be replayed.
    if callable(source):
        return source
    return lambda: iter(source)


def _raw(source):
    # A Resumable handed in as a source contributes its raw source, so a
    # derived stream replays the pipeline from the start and leaves the
    # original's own position where it was.
    if isinstance(source, Resumable):
        return source.source
    return _factory(source)


class _Cursor:
    """The bottom of a pipeline: the source iterator and the count taken.

    This is where a position comes from and where laziness is enforced. Every
    stage sits above the cursor, so the count is items taken from the source
    rather than items handed out, which is what keeps a filtered stream's
    position comparable with the position of the stream underneath it.
    """

    def __init__(self, source, stages=()):
        self._open = _factory(source)
        self._stages = tuple(stages)
        self.pos = 0
        self._items = self._rebuild()

    def _rebuild(self):
        stream = self._open()
        # Counted before the stages, so an item the stages go on to reject
        # still moves the position. That is what makes a filtered stream's
        # snapshot mean the same thing as the snapshot of its source.
        stream = self._counted(stream)
        for stage in self._stages:
            stream = stage(stream)
        return iter(stream)

    def _counted(self, stream):
        for item in stream:
            self.pos += 1
            yield item

    def __iter__(self):
        return self

    def __next__(self):
        return next(self._items)

    def restore(self, pos):
        # The hard part. A generator cannot be rewound, so the only way back is
        # to run the source again and throw the output away. Rebuilding the
        # stages as well as the source is what re-applies a filter.
        self.pos = 0
        self._items = self._rebuild()
        while self.pos < pos:
            try:
                next(self._items)
            except StopIteration:
                # The source is shorter than the position. Restoring past the
                # end leaves the stream exhausted, which is not an error.
                break


class Resumable:
    """A cursor over a stream of raw items that can be put back.

    The source is never materialised. It is either a zero-argument callable
    returning a fresh iterator, or a container that can be walked more than
    once, and every next() pulls exactly the items it needs and no more.
    """

    def __init__(self, source, stages=()):
        self.source = _raw(source)
        self._cursor = _Cursor(self.source, stages)

    def snapshot(self):
        return self._cursor.pos

    def restore(self, pos):
        self._cursor.restore(pos)

    def next(self, n):
        last = None
        for _ in range(n):
            try:
                last = next(self._cursor)
            except StopIteration:
                # Everything that was left has been consumed, and the answer is
                # -1 because there were not n items to give.
                return -1
        return last


def _joined(first, second):
    for source in (first, second):
        for item in source():
            yield item


def chain(a, b):
    """a's items, then b's items, as one stream.

    The position is a count into the concatenation, so restoring walks a and
    then b until it has passed it.
    """
    first, second = _raw(a), _raw(b)
    return Resumable(lambda: _joined(first, second))


def _only(pred):
    def stage(stream):
        return (item for item in stream if pred(item))

    return stage


def filtered(pred, source):
    # The predicate is part of what the position means, so it lives in the
    # pipeline and is rebuilt on restore rather than being dropped.
    return Resumable(source, (_only(pred),))


def _limited(stream, n):
    count = 0
    while count < n:
        count += 1
        yield next(stream)


def _head(n):
    def stage(stream):
        return _limited(stream, n)

    return stage


def taken(n, source):
    # Stopping after exactly n pulls keeps the position at n: the stage never
    # reaches for one more item to discover that the stream has ended.
    return Resumable(source, (_head(n),))


class JsonObjects:
    """A re-iterable stream of the JSON objects hidden in a chunked text.

    The scan keeps its place across chunk boundaries, so an object split
    anywhere, even one character at a time, is delivered once and whole.
    """

    def __init__(self, chunks):
        self.chunks = chunks

    def __iter__(self):
        buffer = ''
        scan = 0
        depth = 0
        in_string = False
        escaped = False
        for chunk in self.chunks:
            if isinstance(chunk, bytes):
                chunk = chunk.decode('utf-8')
            buffer += chunk
            while scan < len(buffer):
                ch = buffer[scan]
                if in_string:
                    # Inside a string only the escape rules apply: a brace is
                    # data and an escaped quote does not close anything.
                    if escaped:
                        escaped = False
                    elif ch == '\\':
                        escaped = True
                    elif ch == '"':
                        in_string = False
                elif ch == '"':
                    in_string = True
                elif ch == '{':
                    depth += 1
                elif ch == '}':
                    depth -= 1
                    if depth == 0:
                        text = buffer[:scan + 1]
                        buffer = buffer[scan + 1:]
                        scan = 0
                        yield json.loads(text)
                        continue
                scan += 1
            if depth == 0:
                # Nothing is open, so whatever the scan has passed is
                # whitespace between objects and can be dropped.
                buffer = buffer[scan:]
                scan = 0

