import json

CURRENT_VERSION = 2


def _from_v1(payload):
    # v1 nested the state under "data"; v2 lifted it to the top level.
    if 'data' not in payload:
        raise ValueError('v1 payload has no data')
    return payload['data']


# Each entry upgrades a payload by exactly one version, so a future change
# adds one step instead of rewriting every reader.
MIGRATIONS = {1: _from_v1}


class RecordCodec:
    """Reads and writes the record format.

    encode is the only writer of this format and decode the only reader, so
    the two cannot drift. The version is in the text, which is what lets a log
    written last year be read today.
    """

    CURRENT = CURRENT_VERSION

    def __init__(self, version=None):
        self.version = self.CURRENT if version is None else version

    def encode(self, state):
        # Sorted keys make the text canonical: two equal states encode to the
        # same bytes, which is what a checksum or a diff can rely on.
        return 'v%d %s' % (self.version, json.dumps(state, sort_keys=True))

    def decode(self, text):
        header, space, payload = text.partition(' ')
        if not space or not header.startswith('v'):
            raise ValueError('missing version header')
        try:
            version = int(header[1:])
        except ValueError:
            raise ValueError('unreadable version')
        if version > self.version:
            # A record from the future is refused rather than misread: data
            # this reader cannot understand must never look like valid data.
            raise ValueError('unsupported version')
        data = json.loads(payload)
        while version < self.version:
            if version not in MIGRATIONS:
                raise ValueError('no migration from version %d' % version)
            data = MIGRATIONS[version](data)
            version += 1
        return data


class Journal:
    """An append-only log of records, replayed to rebuild the state."""

    def __init__(self, codec=None):
        self.codec = RecordCodec() if codec is None else codec
        # Raw lines exactly as a writer left them, newline included or not.
        self.log = []

    def _write(self, record):
        self.log.append(self.codec.encode(record) + '\n')

    def append(self, key, value, now):
        self._write({'key': key, 'value': value, 'deleted': False, 'at': now})

    def remove(self, key, now):
        # A tombstone is a record, not an absence. Without one the key would
        # come back the next time the log was replayed from an older prefix.
        self._write({'key': key, 'value': None, 'deleted': True, 'at': now})

    def append_raw(self, text):
        self.log.append(text)

    def _entries(self):
        lines = ''.join(self.log).split('\n')
        lines.pop()
        # A crash can only tear the last write, so whatever follows the final
        # newline is a record that never finished and is dropped. Every other
        # line is complete and must decode, or the log itself is corrupt.
        for line in lines:
            yield self.codec.decode(line)

    def _apply(self, state, record):
        if record['deleted']:
            state.pop(record['key'], None)
        else:
            state[record['key']] = record['value']

    def load(self, now):
        state = {}
        for record in self._entries():
            if record['at'] > now:
                # Stamped for a time we have not reached yet.
                continue
            self._apply(state, record)
        return state

    def snapshot(self, now):
        state = {}
        at = 0
        for record in self._entries():
            if record['at'] > now:
                continue
            at += 1
            self._apply(state, record)
        # at counts the records folded in. Stamps are nondecreasing, so those
        # records are a prefix of the log and the count is a usable position.
        return {'at': at, 'now': now, 'data': self.codec.encode(state)}

    def restore(self, snapshot, now):
        if now < snapshot['now']:
            raise ValueError('cannot restore to a time before the snapshot')
        state = self.codec.decode(snapshot['data'])
        seen = 0
        for record in self._entries():
            if seen < snapshot['at']:
                # The snapshot is believed rather than checked, and the log is
                # left alone: restore is positional and does not compact.
                seen += 1
                continue
            if record['at'] > now:
                continue
            self._apply(state, record)
        return state

