import re

ERROR = 'error'
FUNCTIONS = ('SUM', 'MIN', 'MAX', 'AVG', 'COUNT')
CELL = re.compile(r'([A-Za-z]+)([0-9]+)')
TOKEN = re.compile(r'[0-9]+(?:\.[0-9]+)?|[A-Za-z]+[0-9]*|[-+*/(),:]|\s+')
PRECEDENCE = {'+': 1, '-': 1, '*': 2, '/': 2}
BINARY = {'+': lambda a, b: a + b, '-': lambda a, b: a - b, '*': lambda a, b: a * b,
          '/': lambda a, b: ERROR if b == 0 else a / b}
AGGREGATE = {'SUM': sum, 'MIN': min, 'MAX': max, 'COUNT': len,
             'AVG': lambda values: sum(values) / len(values)}


def locate(ref):
    """Turn 'AA10' into (10, 27), the column being base 26, 1-based.

    A cell is a (row, column) pair, so a range's ends decide its order.
    """
    m = CELL.fullmatch(ref)
    if not m or int(m.group(2)) < 1:
        raise ValueError('Bad cell reference: ' + ref)
    col = 0
    for ch in m.group(1).upper():
        col = col * 26 + (ord(ch) - 64)
    return (int(m.group(2)), col)


def _classify(text):
    if text[0] in '+-*/(),:':
        return 'op', text
    if '0' <= text[0] <= '9':
        return 'num', float(text) if '.' in text else int(text)
    # Letters followed by digits is a cell; letters alone is a name.
    return ('ref' if '0' <= text[-1] <= '9' else 'name'), text.upper()


def tokenize(source):
    """One pass over the formula, refusing anything it does not recognise."""
    raw = TOKEN.findall(source)
    if ''.join(raw) != source:
        # findall skips what it cannot match, so compare coverage instead.
        raise ValueError('Unexpected character in: ' + source)
    return [_classify(text) for text in raw if text[0] not in ' \t\n\r']


class Parser:
    """Recursive descent, recording every cell it read on the way past."""

    def __init__(self, tokens):
        self.tokens = tokens
        self.i = 0
        self.refs = set()

    def peek(self):
        return self.tokens[self.i] if self.i < len(self.tokens) else None

    def take(self, kind=None, value=None):
        self.i += 1
        if self.i > len(self.tokens):
            raise ValueError('Formula ends early')
        token = self.tokens[self.i - 1]
        if kind is not None and token != (kind, value):
            raise ValueError('Expected ' + value)
        return token

    def expression(self, floor=1):
        node = self.unary()
        while (token := self.peek()) and PRECEDENCE.get(token[1], 0) >= floor:
            # Climb from the operator's own precedence, so 2 + 3 * 4 is
            # 2 + (3 * 4) and never (2 + 3) * 4.
            op = self.take()[1]
            node = ('bin', op, node, self.expression(PRECEDENCE[op] + 1))
        return node

    def unary(self):
        """A primary, with as many leading minuses as the formula has."""
        kind, value = self.take()
        if kind == 'num':
            return ('num', value)
        if kind == 'ref':
            return self.reference(value)
        if kind == 'name':
            return self.call(value)
        if value == '-':
            # A leading minus is a multiply by -1, so -2 * 3 is (-2) * 3 and the
            # tree only ever holds the two node kinds below.
            return ('bin', '*', ('num', -1), self.unary())
        if value != '(':
            raise ValueError('Unexpected token: ' + repr(value))
        node = self.expression()
        self.take('op', ')')
        return node

    def reference(self, ref):
        key = locate(ref)
        self.refs.add(key)
        if self.peek() != ('op', ':'):
            return ('ref', key)
        self.take()
        nxt = self.take()
        if nxt[0] != 'ref':
            raise ValueError('A range needs a second cell')
        span = (key, locate(nxt[1]))
        if span[0] > span[1]:
            # B2:A1 is a typo. Swapping the ends invents a range nobody wrote.
            raise ValueError('Reversed range: ' + ref + ':' + nxt[1])
        cells = [(row, col) for row in range(key[0], span[1][0] + 1)
                 for col in range(key[1], span[1][1] + 1)]
        self.refs.update(cells)
        return ('range', cells)

    def call(self, name):
        if name not in FUNCTIONS:
            raise ValueError('Unknown function: ' + name)
        self.take('op', '(')
        args = []
        while self.peek() and self.peek()[0] == 'ref':
            args.append(self.unary())
            if self.peek() != ('op', ','):
                break
            self.take()
        if not args:
            # An argument is a cell or a range, never an expression, or
            # SUM(A1*2) would quietly become a different question.
            raise ValueError(name + ' takes a cell or range')
        self.take('op', ')')
        return ('call', name, args)


def parse(source):
    parser = Parser(tokenize(source))
    node = parser.expression()
    if parser.i != len(parser.tokens):
        # Dropped trailing junk turns a typo into a plausible answer.
        raise ValueError('Trailing input in formula')
    return node, parser.refs


class Sheet:
    """A spreadsheet whose formulas are a language: parse one, then run one.

    A write is one evaluation and nothing knows what depends on what.
    """

    def __init__(self):
        self.values = {}

    def get(self, cell):
        # An unset cell reads as 0, the same value inside every formula.
        return self.values.get(locate(str(cell)), 0)

    def set(self, cell, value):
        # A cell holds a number or an '= formula', nothing else.
        if isinstance(value, str):
            if not value.startswith('='):
                raise ValueError('A text cell value must start with =')
            # Parsed before anything is stored, so a bad one changes nothing.
            value = self._eval(parse(value[1:])[0])
        elif not isinstance(value, (int, float)) or isinstance(value, bool):
            raise ValueError('A cell holds a number or a formula')
        self.values[locate(str(cell))] = value
        return value

    def evaluate(self, formula):
        # Ad hoc: it reads current values and stores nothing.
        if not isinstance(formula, str) or not formula.startswith('='):
            raise ValueError('A formula starts with =')
        return self._eval(parse(formula[1:])[0])

    def _eval(self, node):
        kind = node[0]
        if kind == 'num':
            return node[1]
        if kind == 'ref':
            return self.values.get(node[1], 0)
        if kind == 'range':
            return [self.values.get(cell, 0) for cell in node[1]]
        if kind == 'bin':
            left, right = self._eval(node[2]), self._eval(node[3])
            if left == ERROR or right == ERROR:
                return ERROR  # One bad input poisons the whole expression.
            return BINARY[node[1]](left, right)
        values = []
        for arg in node[2]:
            flat = self._eval(arg)
            values += flat if isinstance(flat, list) else [flat]
        if ERROR in values:
            return ERROR
        return AGGREGATE[node[1]](values)

