RESERVED = 'key'


def rank_of(value):
    """Rank a column value into one total order.

    A row without a value gets a rank of its own and so never reaches the
    value comparison at all. Numbers rank before strings, which is what keeps
    a mixed column sorting instead of raising on the first int/str pair.
    """
    if value is None:
        return (0, 0, 0)
    if isinstance(value, (int, float)) and not isinstance(value, bool):
        return (1, 0, value)
    return (1, 1, value)


def sort_key(row, column):
    # Ties fall back to the key, so two rows with the same column value always
    # come back in the same order no matter how they were written.
    return rank_of(row.get(column)) + (row[RESERVED],)


class TableStore:
    """Tables of rows keyed by a key column, with deletes kept as tombstones.

    Every answer here is decided by the keys and the columns, never by the
    order writes happened to arrive in, so replaying the same operations
    always produces the same rows. That is what makes a query log worth
    replaying in the first place.
    """

    def __init__(self):
        # table -> key -> (row, deleted flag)
        self.rows = {}
        # table -> key -> every version written, None marking each tombstone
        self.versions = {}
        # table -> every column ever seen, because columns are never dropped
        self.columns = {}

    def insert(self, table, row):
        if not isinstance(row, dict) or RESERVED not in row:
            raise ValueError('A row is a dict with a key column')
        key = row[RESERVED]
        if not isinstance(key, int) or isinstance(key, bool):
            raise ValueError('Keys are integers')
        for value in row.values():
            if value is not None and not isinstance(value, (int, float, str)):
                raise ValueError('Values are numbers, strings or None')
        record = dict(row)
        # Re-inserting a deleted key clears its tombstone instead of failing,
        # so one key space stays one key space rather than splitting in two.
        self.rows.setdefault(table, {})[key] = (record, False)
        self.columns.setdefault(table, set()).update(row)
        self.versions.setdefault(table, {}).setdefault(key, []).append(record)
        return dict(record)

    def update(self, table, key, changes):
        record = self.rows.get(table, {}).get(key)
        if record is None or record[1]:
            return None
        if RESERVED in changes:
            raise ValueError('The key column is fixed')
        seen = self.columns.get(table, ())
        for column in changes:
            if column not in seen:
                # An update never invents a column. Otherwise a typo becomes
                # a real column that nothing else agrees exists.
                raise ValueError('Unknown column: ' + str(column))
        # A new dict rather than an in-place change, so the previous version
        # stays intact for history.
        merged = dict(record[0])
        merged.update(changes)
        self.rows[table][key] = (merged, False)
        self.versions.setdefault(table, {}).setdefault(key, []).append(merged)
        return dict(merged)

    def delete(self, table, key):
        record = self.rows.get(table, {}).get(key)
        if record is None or record[1]:
            # Deleting what is not there changes nothing, tombstone log
            # included, so a repeated delete cannot inflate the history.
            return False
        # The row stays where it is so history can still be reconstructed; only
        # the flag moves, and every read path checks it.
        self.rows[table][key] = (record[0], True)
        self.versions.setdefault(table, {}).setdefault(key, []).append(None)
        return True

    def select(self, table, where=None, order_by=None, desc=False, limit=None):
        if limit is not None and limit < 0:
            raise ValueError('limit is a nonnegative integer')
        rows = [
            dict(row)
            for row, deleted in self.rows.get(table, {}).values()
            if not deleted
        ]
        if where is not None:
            rows = [row for row in rows if where(row)]
        if order_by is None:
            rows.sort(key=lambda row: row[RESERVED])
        else:
            rows.sort(key=lambda row: sort_key(row, order_by))
        if desc:
            # Reversing the finished list rather than flipping each comparison
            # keeps descending the exact mirror of ascending, ties included.
            rows.reverse()
        if limit is not None:
            rows = rows[:limit]
        return rows

    def include_deleted(self, table):
        """(key, row) pairs by ascending key, None standing for a tombstone."""
        return [
            (key, None if deleted else dict(row))
            for key, (row, deleted) in sorted(self.rows.get(table, {}).items())
        ]

    def history(self, table, key):
        """Every version written for one key in write order, None per delete."""
        return [
            None if row is None else dict(row)
            for row in self.versions.get(table, {}).get(key, ())
        ]

    def schema(self, table):
        # The union over every version, so a column that only one row ever had
        # is still part of the table's shape.
        return sorted(self.columns.get(table, ()))
